更新数据哈
r.GET("/update", func(c *gin.Context) {
		// 查询id等于6的数据
		class := modules.Class{ID: 6}
		modules.DB.Find(&class)
		// 修改班级名称为周末2
		class.Name = "周末2"
		// 修改班级成绩为34
		class.Score = 34
		modules.DB.Save(&class)
		c.JSON(200, gin.H{
			"msg":   "查询更改",
			"class": class,
		})
	})


另外一种方式进行更新
	r.GET("/update", func(c *gin.Context) {
		// 更新id等于6的数据
		class := modules.Class{}
		modules.DB.Where("id = ?", 6).First(&class)
		// 修改班级名称为周末3
		class.Name = "周末3"
		// 修改班级成绩为34
		class.Score = 34
		modules.DB.Save(&class)
		c.JSON(200, gin.H{
			"msg":   "更新班级成功",
			"class": class,
		})
	})


